INSERT INTO journey_session (
    id, traveler_profile_id, line_id, direction_id, boarding_stop_id,
    alighting_stop_id, target_probability, desired_arrival_at, status,
    expires_at, created_at, updated_at
) VALUES (
    #{id}, #{travelerProfileId}, #{lineId}, #{directionId}, #{boardingStopId},
    #{alightingStopId}, #{targetProbability}, #{desiredArrivalAt}, #{status},
    #{expiresAt}, #{createdAt}, #{updatedAt}
)

mapper.update:
UPDATE journey_session
SET status = #{status},
    updated_at = #{updatedAt}
WHERE id = #{id}

UPDATE journey_session
SET status = 'EXPIRED',
    updated_at = #{updatedAt}
WHERE id IN (
    SELECT id
    FROM journey_session
    WHERE status = 'ACTIVE'
      AND expires_at  <=  #{asOf}
    ORDER BY expires_at ASC, id ASC
    LIMIT #{limit}
)
